function reset3D(){if(!campus3D)return;const bounds=new maplibregl.LngLatBounds();for(const f of threeFeatures.filter(f=>names[f.id]))for(const p of f.points)bounds.extend(p);if(!bounds.isEmpty())campus3D.fitBounds(bounds,{padding:{top:140,bottom:155,left:35,right:75},maxZoom:16.4,bearing:-18,pitch:52,duration:650})}
function set3D(on){if(on&&!threeReady){document.querySelector('#height-summary').textContent='3D is still loading, or unavailable in this browser. The 2D map remains usable.';return}is3D=on;document.body.classList.toggle('is-3d',on);threeContainer.hidden=!on;document.querySelector('#view-2d').setAttribute('aria-pressed',String(!on));document.querySelector('#view-3d').setAttribute('aria-pressed',String(on));document.querySelector('#camera-tools').hidden=!on;if(on){campus3D.resize();sync3D()}else document.querySelector('.north span').style.transform=''}
document.querySelector('#view-2d').onclick=()=>set3D(false);document.querySelector('#view-3d').onclick=()=>set3D(true);
for(const [id,amount]of [['rotate-left',-30],['rotate-right',30]])document.querySelector('#'+id).onclick=()=>campus3D?.easeTo({bearing:campus3D.getBearing()+amount,duration:450});document.querySelector('#tilt-camera').onclick=()=>campus3D?.easeTo({pitch:campus3D.getPitch()>40?20:60,duration:450});
for(const id of ['plus','minus','reset']){const b=document.querySelector('#'+id),old=b.onclick;b.onclick=()=>{if(!is3D)return old();if(id==='plus')campus3D.zoomIn();if(id==='minus')campus3D.zoomOut();if(id==='reset')reset3D()}}
let frame=0;new MutationObserver(()=>{if(!threeReady)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(sync3D)}).observe(world,{subtree:true,attributes:true,attributeFilter:['class']});new MutationObserver(()=>{if(threeReady)sync3D()}).observe(svg,{attributes:true,attributeFilter:['class']});
(async()=>{try{const urls=['campus.json','heights.json','parking.json'];const responses=await Promise.all(urls.map(url=>fetch(url)));if(responses.some(r=>!r.ok))throw Error('Missing campus data');[threeFeatures,threeHeights,threeParking]=await Promise.all(responses.map(r=>r.json()));
threeContainer.hidden=false;campus3D=new maplibregl.Map({container:threeContainer,center:[-112.864,49.6785],zoom:16.4,bearing:-18,pitch:52,maxPitch:70,minZoom:14,maxZoom:20,maxBounds:[[-112.89,49.662],[-112.84,49.697]],attributionControl:false,style:{version:8,sources:{},layers:[{id:'background',type:'background',paint:{'background-color':'#edf0e6'}}]}});
campus3D.on('error',e=>{console.warn('3D map:',e.error?.message);});
campus3D.on('load',()=>{const areas=threeFeatures.filter(f=>!f.tags.building&&!f.tags.highway&&f.points.length>3&&['water','grass','park','garden','pitch','recreation_ground'].some(v=>Object.values(f.tags).includes(v))).map(f=>({type:'Feature',properties:{color:f.tags.natural==='water'?'#c6dad9':'#dce5ce'},geometry:{type:'Polygon',coordinates:[closeRing(f.points)]}}));add3DSource('areas',areas);campus3D.addLayer({id:'areas',type:'fill',source:'areas',paint:{'fill-color':['get','color']}});
const paths=threeFeatures.filter(f=>f.tags.highway).map(f=>{const t=f.tags;const walk=['footway','path','pedestrian','steps'].includes(t.highway)||(t.highway==='cycleway'&&['yes','designated','permissive'].includes(t.foot));return {type:'Feature',properties:{foot:walk,stairs:t.highway==='steps',trail:['gravel','dirt','ground','unpaved','earth','compacted'].includes(t.surface)||t.highway==='path',restricted:['no','private'].includes(t.foot)||t.access==='private',shared:t.highway==='cycleway'},geometry:{type:'LineString',coordinates:f.points}}});add3DSource('paths',paths);
campus3D.addLayer({id:'roads',type:'line',source:'paths',filter:['==',['get','foot'],false],paint:{'line-color':'#fffdf4','line-width':['interpolate',['linear'],['zoom'],14,2,18,15]},layout:{'line-cap':'round','line-join':'round'}});
const publicWalk=['all',['==',['get','foot'],true],['==',['get','restricted'],false]];
campus3D.addLayer({id:'walkway-edges',type:'line',source:'paths',filter:publicWalk,paint:{'line-color':'#a8a18c','line-width':['interpolate',['linear'],['zoom'],14,1.5,16,3.5,18,10,20,30]},layout:{'line-cap':'round','line-join':'round'}});
campus3D.addLayer({id:'walkways',type:'line',source:'paths',filter:publicWalk,paint:{'line-color':['case',['get','trail'],'#d9c5a3','#f1e9d6'],'line-width':['interpolate',['linear'],['zoom'],14,.8,16,2.5,18,8,20,26]},layout:{'line-cap':'round','line-join':'round'}});
campus3D.addLayer({id:'trail-marks',type:'line',source:'paths',filter:['all',publicWalk,['==',['get','trail'],true]],paint:{'line-color':'#ad916a','line-width':1,'line-dasharray':[2,4]}});
campus3D.addLayer({id:'stair-marks',type:'line',source:'paths',filter:['all',publicWalk,['==',['get','stairs'],true]],paint:{'line-color':'#8b725c','line-width':['interpolate',['linear'],['zoom'],16,3,19,12],'line-dasharray':[.2,1.2]}});
add3DSource('parking3d',threeParking.filter(f=>f.tags.name).map(f=>({type:'Feature',properties:{name:f.tags.name},geometry:{type:'Polygon',coordinates:[closeRing(f.points)]}})));campus3D.addLayer({id:'parking-fill',type:'fill',source:'parking3d',layout:{visibility:'none'},paint:{'fill-color':'#b6c9e3','fill-opacity':.8}});campus3D.addLayer({id:'parking-outline',type:'line',source:'parking3d',layout:{visibility:'none'},paint:{'line-color':'#6483ad','line-width':1.5}});
add3DSource('buildings',[]);campus3D.addLayer({id:'building-volumes',type:'fill-extrusion',source:'buildings',paint:{'fill-extrusion-color':['get','color'],'fill-extrusion-height':['get','height'],'fill-extrusion-base':0,'fill-extrusion-opacity':.96,'fill-extrusion-vertical-gradient':true}});campus3D.setLight({anchor:'viewport',color:'#fff9e7',intensity:.45,position:[1.5,160,45]});
add3DSource('architecture',architectureDetails(threeFeatures,threeHeights));campus3D.addLayer({id:'architecture-details',type:'fill-extrusion',source:'architecture',minzoom:15.4,paint:{'fill-extrusion-color':['get','color'],'fill-extrusion-base':['get','base'],'fill-extrusion-height':['get','height'],'fill-extrusion-opacity':1,'fill-extrusion-vertical-gradient':false}});campus3D.on('click','architecture-details',e=>{const id=e.features?.[0]?.properties.id;if(id)openBuilding(String(id))});campus3D.on('click','building-volumes',e=>{const id=e.features?.[0]?.properties.id;if(id)openBuilding(String(id))});campus3D.on('mouseenter','building-volumes',()=>campus3D.getCanvas().style.cursor='pointer');campus3D.on('mouseleave','building-volumes',()=>campus3D.getCanvas().style.cursor='');campus3D.on('rotate',()=>{if(is3D)document.querySelector('.north span').style.transform='rotate('+(-campus3D.getBearing())+'deg)'});threeReady=true;setupBuildingInspector();const matched=Object.values(threeHeights).filter(h=>h.source.startsWith('City')).length;document.querySelector('#height-summary').textContent=matched+' of '+Object.keys(threeHeights).length+' footprints matched to city elevation records. Remaining heights are estimates. Extrusion heights do not reproduce building floor levels or hillside terrain.';set3D(true);reset3D();
});}catch(e){threeContainer.hidden=true;document.querySelector('#height-summary').textContent='3D could not start on this browser. Use the existing 2D campus map.';document.querySelector('#model-info').open=true;console.warn(e)}})();

let inspectedBuilding='';
function setupBuildingInspector(){const select=document.querySelector('#inspect-building');for(const f of threeFeatures.filter(f=>names[f.id])){const option=document.createElement('option');option.value=f.id;option.textContent=names[f.id].filter(v=>typeof v==='string').join(' ');select.append(option)}select.onchange=()=>{inspectedBuilding=select.value;if(!inspectedBuilding){reset3D();return}setFoodMode(false);setVendingMode(false);setParkingMode(false);set3D(true);const f=threeFeatures.find(f=>f.id===inspectedBuilding);campus3D.flyTo({center:centerOf(f.points),zoom:17.7,pitch:65,bearing:-25,duration:900});const profile=architectureProfiles[f.id];document.querySelector('#architecture-note').textContent=(profile.provisional?'Provisional exterior. ':'Photo-guided interpretation. ')+profile.note;const link=document.querySelector('#architecture-source');link.href=profile.source;link.textContent=profile.provisional?'Building information ↗':'View original reference page ↗';document.querySelector('#model-info').open=true;sync3D()};
let labelFrame=0;campus3D.on('moveend',()=>{cancelAnimationFrame(labelFrame);labelFrame=requestAnimationFrame(declutter3DLabels)});declutter3DLabels()}
function declutter3DLabels(){if(!threeReady)return;const occupied=[];const bounds=threeContainer.getBoundingClientRect();for(const marker of threeMarkers){const e=marker.getElement();e.style.visibility='visible';const r=e.getBoundingClientRect();const overlaps=occupied.some(b=>!(r.right+5<b.left||r.left>b.right+5||r.bottom+4<b.top||r.top>b.bottom+4));if(overlaps||r.top<bounds.top+112||r.bottom>bounds.bottom-105||r.left<bounds.left||r.right>bounds.right)e.style.visibility='hidden';else occupied.push(r)}}
